"""Ensaio reversível de Ordem Cronológica; nenhum dado institucional."""
from pathlib import Path
import argparse,re
ROOT=Path(__file__).resolve().parents[1]
PAGE=ROOT/'dist/Portal-da-Transparencia/Contratos/OrdemCronologica/index.html'
NOTICE='DADO SINTÉTICO — TESTE SERIGY'
BASE_MAIN = '<main id="conteudo" class="container" serigySchema="https://serigy.tce.se.gov.br/comum/contratos.html">\n    <h1>Ordem Cronológica</h1>\n    <p class="section-availability" role="note">As informações desta seção ainda serão disponibilizadas.</p>\n    <p class="section-availability">Consulta e exportação indisponíveis enquanto os dados e documentos não forem disponibilizados.</p>\n    <p class="lead">Ordem cronológica dos créditos e pagamentos, por fonte de recursos e categoria contratual, com justificativas das alterações.</p>\n    <form id="filtro-ordem" class="filter-panel" role="search" aria-label="Consultar ordem cronológica">\n      <div class="field"><label for="ano-ordem">Exercício</label><select id="ano-ordem" name="ano" disabled><option value="" selected disabled>Selecione o exercício</option></select></div>\n      <div class="field"><label for="mes-ordem">Mês de referência</label><select id="mes-ordem" name="mes" disabled><option value="" selected disabled>Selecione o mês</option></select></div>\n      <div class="field"><label for="fonte-ordem">Fonte dos recursos</label><select id="fonte-ordem" name="fonte" disabled><option value="" selected disabled>Selecione a fonte</option></select></div>\n      <div class="field"><label for="categoria-ordem">Categoria contratual</label><select id="categoria-ordem" name="categoria" disabled><option value="" selected disabled>Selecione a categoria</option></select></div>\n      <div class="filter-actions">\n        <button id="pesquisar-ordem" type="submit" disabled>Pesquisar</button>\n        <button type="reset" class="secondary" disabled>Limpar filtros</button>\n      </div>\n    </form>\n    <section id="resultados-ordem" aria-labelledby="titulo-relacao-ordem">\n      <h2 id="titulo-relacao-ordem">Ordem Cronológica</h2>\n      <div class="exports"><button id="exportar-ordem" type="button" disabled>Exportar conjunto selecionado</button></div>\n      <div class="table-wrap">\n        <table id="tabela-ordem">\n          <caption>Ordem Cronológica</caption>\n          <thead><tr><th scope="col">Fonte dos recursos</th><th scope="col">Categoria contratual</th><th scope="col">Data de vencimento</th><th scope="col">Data de pagamento</th><th scope="col">Credor</th><th scope="col">Valor do pagamento</th><th scope="col">Justificativa de alteração</th></tr></thead>\n          <tbody id="registros-ordem"></tbody>\n        </table>\n      </div>\n    </section>\n    <section id="justificativas-ordem" aria-labelledby="titulo-justificativas-ordem">\n      <h2 id="titulo-justificativas-ordem">Justificativas de alterações da ordem</h2>\n      <div id="identificacao-credito-ordem"></div>\n      <div id="texto-justificativa-ordem"></div>\n      <ul id="documentos-justificativas-ordem"></ul>\n    </section>\n    <div id="atualizacao-ordem" class="update-info"></div>\n  </main>'  # preenchido com a estrutura anterior antes da primeira ativação
def render(active=True):
    main=BASE_MAIN
    if active:
        rows=[]
        for i,year in enumerate([2023,2024,2025,2026],1):
            rows.append(f'<tr data-dado-sintetico="ordem" data-year="{year}" data-mes="10"><td>{NOTICE}</td><td serigyItem="dataVencimento">10/10/{year}</td><td serigyItem="dataPagamento">12/10/{year}</td><td serigyItem="credor">CREDOR FICTÍCIO DE ENSAIO {i} — NÃO EXISTE</td><td serigyItem="valorPagamento">R$ {i*100},00</td></tr>')
        options=''.join(f'<option value="{y}" serigyValue="{y}">{y}</option>' for y in [2026,2025,2024,2023])
        main='<main id="conteudo" class="container" serigySchema="https://serigy.tce.se.gov.br/comum/contratos.html"><h1>Ordem Cronológica</h1><section data-dado-sintetico="ordem"><h2>Ensaio técnico — pagamentos sintéticos</h2><p role="note"><strong>'+NOTICE+'</strong>. Estes registros não representam pagamentos, credores ou ordem cronológica do SergipePrevidência.</p><form id="filtro-ordem" class="filter-panel" serigyItem="filtroPesquisa" aria-label="Consultar pagamentos sintéticos"><div class="field"><label for="ano-ordem">Exercício sintético</label><select id="ano-ordem" name="ano" serigyItem="historicoExercicio" serigyExecuteWaitSection="ordemTabela"><option value="">Todos</option>'+options+'</select></div><div class="field"><label for="mes-ordem">Mês de pagamento sintético</label><select name="mes" id="mes-ordem"><option value="">Todos</option><option value="10">Outubro</option></select></div><div class="field"><label for="credor-ordem">Credor fictício</label><input type="search" id="credor-ordem" name="credor"></div><button type="submit" serigyExecuteWaitSection="ordemTabela">Pesquisar</button><button type="reset" serigyClearForm>Limpar filtros</button></form><section serigyLoadSection="ordemTabela" aria-label="Resultado do ensaio"><p id="contagem-ordem" role="status" aria-live="polite">4 pagamentos sintéticos.</p><button type="button" id="exportar-ordem" serigyItem="salvarRelatorio" serigyValue="csv">CSV do recorte sintético</button><div class="table-wrap"><table id="tabela-ordem"><caption>'+NOTICE+'</caption><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in ['Identificação do ensaio','Data de vencimento sintética','Data de pagamento sintética','Credor fictício','Valor sintético'])+'</tr></thead><tbody>'+''.join(rows)+'</tbody></table></div></section><p class="update-info">Informações atualizadas em <span serigyItem="dataUltimaAtualizacao">22/10/2026</span> — data de preparação do ensaio, não de atualização de pagamentos oficiais.</p></section></main>'
    assert main
    old=PAGE.read_text(encoding='utf-8')
    new=re.sub(r'<main\b.*?</main>',lambda _:main,old,count=1,flags=re.S)
    script='<script defer src="/assets/js/ordem-teste.js"></script>'
    new=new.replace(script+'\n','').replace(script,'')
    if active:new=new.replace('</head>',script+'\n</head>')
    return new
if __name__=='__main__':
    p=argparse.ArgumentParser();g=p.add_mutually_exclusive_group(required=True);g.add_argument('--ativar',action='store_true');g.add_argument('--desativar',action='store_true');p.add_argument('--check',action='store_true');args=p.parse_args();content=render(args.ativar)
    if args.check:assert PAGE.read_text(encoding='utf-8')==content
    else:PAGE.write_text(content,encoding='utf-8')
    print('Ordem Cronologica: ensaio '+('ativo' if args.ativar else 'removido')+'.')
